// src/domain/state-machines.ts — Authoritative State Machines for XEURIE 2.0 Entities

import {
  InventoryUnitStatus,
  OrderStatus,
  ReservationStatus,
} from "@/src/types/domain";
import { OrderState } from "@/src/types/order";

export class InvalidStateTransitionError extends Error {
  constructor(
    public entity: string,
    public from: string,
    public to: string,
    message?: string
  ) {
    super(
      message ||
        `Invalid state transition for ${entity}: cannot transition from '${from}' to '${to}'`
    );
    this.name = "InvalidStateTransitionError";
  }
}

// 1. Inventory Unit State Machine (Lock I 13-Stage Lifecycle + Legacy Compatibility)
const INVENTORY_UNIT_TRANSITIONS: Record<InventoryUnitStatus, InventoryUnitStatus[]> = {
  DRAFT: ["SUBMITTED", "PURGED", "ARCHIVED"],
  SUBMITTED: ["UNDER_REVIEW", "NEEDS_REVISION", "APPROVED", "REJECTED"],
  UNDER_REVIEW: ["APPROVED", "NEEDS_REVISION", "REJECTED"],
  NEEDS_REVISION: ["SUBMITTED", "DRAFT", "REJECTED"],
  APPROVED: ["AVAILABLE", "REJECTED"],
  AVAILABLE: ["RESERVED", "DEFECTIVE", "ARCHIVED", "PURGED"],
  RESERVED: ["SOLD", "AVAILABLE", "DEFECTIVE"],
  SOLD: ["WARRANTY_REVIEW", "DEFECTIVE", "ARCHIVED"],
  WARRANTY_REVIEW: ["REPLACEMENT_REQUIRED", "SOLD", "REJECTED", "DEFECTIVE"],
  REPLACEMENT_REQUIRED: ["REPLACED", "DEFECTIVE"],
  REPLACED: ["PURGED", "ARCHIVED"],
  REJECTED: ["PURGED", "DRAFT", "ARCHIVED"],
  PURGED: [],
  DEFECTIVE: ["ARCHIVED", "PURGED", "REPLACEMENT_REQUIRED"],
  ARCHIVED: ["PURGED"],
};

export class InventoryUnitStateMachine {
  static canTransition(
    current: InventoryUnitStatus,
    target: InventoryUnitStatus
  ): boolean {
    if (current === target) return true;
    const allowed = INVENTORY_UNIT_TRANSITIONS[current] || [];
    return allowed.includes(target);
  }

  static transition(
    current: InventoryUnitStatus,
    target: InventoryUnitStatus
  ): InventoryUnitStatus {
    if (!this.canTransition(current, target)) {
      throw new InvalidStateTransitionError("InventoryUnit", current, target);
    }
    return target;
  }
}

// 2. Reservation State Machine
const RESERVATION_TRANSITIONS: Record<ReservationStatus, ReservationStatus[]> = {
  PENDING_RESERVATION: ["RESERVED", "CANCELLED"],
  RESERVED: ["COMMITTED", "EXPIRED", "CANCELLED"],
  COMMITTED: [],
  EXPIRED: [],
  CANCELLED: [],
};

export class ReservationStateMachine {
  static canTransition(
    current: ReservationStatus,
    target: ReservationStatus
  ): boolean {
    if (current === target) return true;
    const allowed = RESERVATION_TRANSITIONS[current] || [];
    return allowed.includes(target);
  }

  static transition(
    current: ReservationStatus,
    target: ReservationStatus
  ): ReservationStatus {
    if (!this.canTransition(current, target)) {
      throw new InvalidStateTransitionError("Reservation", current, target);
    }
    return target;
  }
}

// 3. Order State Machine
const ORDER_TRANSITIONS: Record<OrderStatus, OrderStatus[]> = {
  PENDING: ["RESERVED", "CANCELLED"],
  RESERVED: ["PAID", "CANCELLED"],
  PAID: ["FULFILLED", "REFUNDED"],
  FULFILLED: ["REFUNDED"],
  REFUNDED: [],
  CANCELLED: [],
};

export class OrderStateMachine {
  /**
   * @deprecated Use CanonicalOrderStateMachine for the authoritative 16-state lifecycle.
   */
  static canTransition(current: OrderStatus, target: OrderStatus): boolean {
    if (current === target) return true;
    const allowed = ORDER_TRANSITIONS[current] || [];
    return allowed.includes(target);
  }

  static transition(current: OrderStatus, target: OrderStatus): OrderStatus {
    if (!this.canTransition(current, target)) {
      throw new InvalidStateTransitionError("Order", current, target);
    }
    return target;
  }
}

// 4. Canonical Order State Machine (16-state production lifecycle from order.service.ts)
const CANONICAL_ORDER_TRANSITIONS: Record<OrderState, OrderState[]> = {
  DRAFT: ["PENDING_OWNER", "CANCELLED"],
  PENDING_OWNER: ["ACCEPTED", "PAYMENT_REVIEW", "PENDING_MANUAL_VERIFICATION", "PAID", "DELIVERED", "REJECTED", "CANCELLED"],
  ACCEPTED: ["AWAITING_PAYMENT", "PAYMENT_REVIEW", "PENDING_MANUAL_VERIFICATION", "PAID", "DELIVERED", "CANCELLED"],
  AWAITING_PAYMENT: ["PAYMENT_REVIEW", "PENDING_MANUAL_VERIFICATION", "PAID", "DELIVERED", "CANCELLED"],
  PAYMENT_REVIEW: ["PAID", "DELIVERED", "AWAITING_PAYMENT", "CANCELLED"],
  PENDING_MANUAL_VERIFICATION: ["PAID", "DELIVERED", "COMPLETED", "REJECTED", "CANCELLED"],
  PAID: ["PROCESSING", "DELIVERED", "REFUND_PENDING", "CANCELLED"],
  PROCESSING: ["DELIVERED", "REFUND_PENDING", "CANCELLED"],
  DELIVERED: ["COMPLETED", "REPLACEMENT_PENDING", "REFUND_PENDING"],
  COMPLETED: ["REPLACEMENT_PENDING", "REFUND_PENDING"],
  CANCELLED: [],
  REJECTED: [],
  REFUND_PENDING: ["REFUNDED", "ACCEPTED"],
  REFUNDED: [],
  REPLACEMENT_PENDING: ["REPLACED", "DELIVERED", "REFUND_PENDING"],
  REPLACED: ["DELIVERED", "COMPLETED"],
};

export class CanonicalOrderStateMachine {
  static canTransition(current: OrderState, target: OrderState): boolean {
    if (current === target) return true;
    const allowed = CANONICAL_ORDER_TRANSITIONS[current] || [];
    return allowed.includes(target);
  }

  static transition(current: OrderState, target: OrderState): OrderState {
    if (!this.canTransition(current, target)) {
      throw new InvalidStateTransitionError("Order", current, target);
    }
    return target;
  }

  static getValidTransitions(state: OrderState): OrderState[] {
    return CANONICAL_ORDER_TRANSITIONS[state] || [];
  }
}

